from collections import Counter

def find_connected_regions(grid, background):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background and (r, c) not in visited:
                color = grid[r][c]
                region = set()
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    region.add((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if (0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited):
                                queue.append((nr, nc))
                regions.append((color, region))

    # Sort by size descending
    regions = sorted(regions, key=lambda x: len(x[1]))
    return regions

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    counts = [c for row in grid for c in row]
    bg_counts = Counter(counts)
    background = max(bg_counts, key=bg_counts.get)

    regions = find_connected_regions(grid, background)

    # Initialize with background
    output = [[background for _ in range(cols)] for _ in range(rows)]

    # Sort by size descending
    regions = sorted(regions, key=lambda x: len(x[1]))

    # STEP 1: Fill actual region pixels only for regions with size > 1
    for color, region in regions:
        if len(region) > 1:
            for r, c in region:
                output[r][c] = color

    # STEP 2: For regions with size > 1, fill their BBOX (overwrites entire bbox)
    for color, region in regions:
        if len(region) > 1:
            rmin = min(r for r,c in region)
            rmax = max(r for r,c in region)
            cmin = min(c for r,c in region)
            cmax = max(c for r,c in region)
            for r in range(rmin, rmax + 1):
                for c in range(cmin, cmax + 1):
                    if 0 <= r < rows and 0 <= c < cols:
                        output[r][c] = color

    return output

